        "NonNegativeReals",
        "NonNegativeIntegers"
      ],
      "plausibility": [
        0.6,
        0.4
      ],
      "majority_option": "NonNegativeReals"
    },
    {
      "decision": "arc_set_orientation",
      "evidence": "\"Moving a car from location 1 to 3 costs 11 units.\" (costs given only for i < j pairs)",
      "options": [
        "only arcs (i,j) with i<j as listed, flow direction i->j",
        "both directions (i,j) and (j,i) with same cost",
        "only arcs (i,j) with i<j but flow may be negative (net flow)"
      ],
      "plausibility": [
        0.7,
        0.2,
        0.1
