        "cost[i][j] applies to flow from i to j (row=origin, column=destination)",
        "cost[i][j] applies to flow from j to i (row=destination, column=origin)"
      ],
      "plausibility": [
        0.95,
        0.05
      ],
      "majority_option": "cost[i][j] applies to flow from i to j (row=origin, column=destination)"
    }
  ]
